ee:message.ee:set-payload:
%dw 2.0
output application/json
import update from dw::util::Values
//variables
var validacionCliente = ((vars.responseParameters.resultados filter ($.Tipo == "CICLOS_FACTURACION"))[0].Valores filter ($.Codigo == vars.responseById.resultados[0].cliente.segmento))
var currentItem = (vars.responseById.resultados[0].items filter ($.idItem == vars.idItem))[0]
var currentBillingAccount = (vars.responseById.resultados[0].cuentasFacturacion filter ($.idCuentaFacturacion == (currentItem.idCuentaFacturacion)))[0]
//validaciones
var validacion1 = ((vars.responseParameters.resultados filter ($.Tipo == "CICLOS_FACTURACION"))[0].Valores filter ($.Codigo == "Demo"))[0].ValorComplemento
var validacion2 = (validacionCliente filter ($.ValorBase == currentItem.productos.clase))[0].ValorComplemento
var validacion3 = (validacionCliente filter ($.ValorBase == "" or $.ValorBase == null))[0].ValorComplemento
var validacion4 = (validacionCliente filter ($.ValorBase == (currentItem.productos.clase ++ "-" ++ (currentBillingAccount.diaFacturacion default ""))))[0].ValorComplemento
//funciones
fun updateBillingCycle(str) = vars.responseById.resultados[0] update "cuentasFacturacion" with 
    ($ map ((item, index) -> 
        if (item.idCuentaFacturacion == currentItem.idCuentaFacturacion) 
            if(item.cicloFacturacion?)item update "cicloFacturacion" with str 
            else item ++ {"cicloFacturacion": str}
        else item))
---
if (currentBillingAccount.demo == true and validacion1 != null)
updateBillingCycle(validacion1)
else if (validacion2 != null)
    updateBillingCycle(validacion2)
    else if (validacion3 != null)
        updateBillingCycle(validacion3)
        else if (validacion4 != null)
            updateBillingCycle(validacion4)
            else null
